gkH(){return"\u0423 \u043c\u044d\u0442\u0430\u0445 \u0431\u044f\u0441\u043f\u0435\u043a\u0456, \u0432\u044b \u043d\u0435 \u043c\u043e\u0436\u0430\u0446\u0435 \u0430\u0434\u043a\u043b\u0431\u0447\u0430\u0443\u044c \u0448\u044b\u0444\u0440\u0430\u0432\u0430\u043d\u043d\u0435 \u045e \u0433\u044d\u0442\u044b\u043c \u0447\u0430\u0446\u0435, \u0434\u0437\u0435 \u044f\u043d\u043e \u0431\u044b\u043b\u043e \u045e\u043a\u043b\u044e\u0447\u0430\u043d\u0430."},
