glR(){return"\u0423\u0432\u0430\u0433\u0430! \u0411\u0435\u0437 \u0443\u043a\u043b\u044e\u0447\u044d\u043d\u043d\u044f \u0440\u044d\u0437\u0435\u0440\u0432\u043e\u0432\u0430\u0433\u0430 \u043a\u0430\u043f\u0456\u0440\u0430\u0432\u0430\u043d\u043d\u044f \u0447\u0430\u0442\u0430\u045e, \u0432\u044b \u0441\u0442\u0440\u0430\u0446\u0456\u0446\u0435 \u0434\u043e\u0441\u0442\u0443\u043f \u0434\u0430 \u0432\u0430\u0448\u044b\u0445 \u0437\u0430\u0448\u044b\u0444\u0440\u0430\u0432\u0430\u043d\u044b\u0445 \u043f\u0430\u0432\u0435\u0434\u0430\u043c\u043b\u0435\u043d\u043d\u044f\u045e. \u041d\u0430\u0441\u0442\u043e\u0439\u043b\u0456\u0432\u0430 \u0440\u044d\u043a\u0430\u043c\u0435\u043d\u0434\u0443\u0435\u0446\u0446\u0430 \u0443\u043a\u043b\u044e\u0447\u044b\u0446\u044c \u0444\u0443\u043a\u043d\u0446\u044b\u044e \u0434\u0430 \u0442\u0430\u0433\u043e, \u044f\u043a \u0432\u044b\u0439\u0441\u0446\u0456."},
