kY(d){return"\u041d\u0435\u043c\u0430\u0433\u0447\u044b\u043c\u0430 \u0434\u0430\u0441\u043b\u0430\u0446\u044c! \u0421\u0435\u0440\u0432\u0435\u0440 \u043f\u0430\u0434\u0442\u0440\u044b\u043c\u043b\u0456\u0432\u0430\u0435 \u0444\u0430\u0439\u043b\u044b \u0434\u0430 "+d+"."},
