gr3(){return"\u041a\u0430\u0440\u044b\u0441\u0442\u0430\u043b\u044c\u043d\u0456\u043a \u0437\u043c\u043e\u0436\u0430 \u0437\u043d\u043e\u045e \u0434\u0430\u043b\u0443\u0447\u044b\u0446\u0446\u0430 \u0434\u0430 \u0447\u0430\u0442\u0443."},
gpL(){return"\u041a\u0430\u0440\u044b\u0441\u0442\u0430\u043b\u044c\u043d\u0456\u043a \u0431\u0443\u0434\u0437\u0435 \u0432\u044b\u0433\u043d\u0430\u043d\u044b, \u0430\u043b\u0435 \u043d\u0435 \u0437\u0430\u0431\u043b\u0430\u043a\u0456\u0440\u0430\u0432\u0430\u043d\u044b. \u0423 \u043f\u0443\u0431\u043b\u0456\u0447\u043d\u044b\u0445 \u0447\u0430\u0442\u0430\u0445, \u0451\u043d \u0437\u043c\u043e\u0436\u0430 \u0434\u0430\u043b\u0443\u0447\u044b\u0446\u0446\u0430 \u0437\u043d\u043e\u045e \u0443 \u043b\u044e\u0431\u044b \u0447\u0430\u0441."},
